package dev.psxlab;
import android.app.Activity;
import android.app.Instrumentation;
import android.os.Bundle;

/** Headless standalone media regressions; all disc content is generated by the test APK. */
public final class BootInstrumentation extends Instrumentation {
    private Bundle arguments;
    @Override public void onCreate(Bundle args){super.onCreate(args);arguments=args;start();}
    @Override public void onStart(){
        Bundle result=new Bundle();
        try{
            if(arguments==null||!"true".equals(arguments.getString("probeDiscFormats")))throw new IllegalArgumentException("Pass probeDiscFormats=true");
            result.putString("stream",DiscMediaVerifier.verify(getTargetContext()));finish(Activity.RESULT_OK,result);
        }catch(Throwable error){result.putString("stream",android.util.Log.getStackTraceString(error));finish(Activity.RESULT_CANCELED,result);}
    }
}
